#!/usr/bin/env node
/**
 * Copies the web front's translation dictionaries (FR key -> EN / DE / ES) into the
 * mobile app, so every string already translated on the web is reused here.
 *
 * Usage (from the app folder): node scripts/sync-i18n.js [path/to/fleet_management_front]
 * Output: src/i18n/base/en.ts, de.ts, es.ts (generated, do not edit by hand).
 */
const fs = require("fs");
const path = require("path");

const appRoot = path.resolve(__dirname, "..");
const webRoot = path.resolve(process.argv[2] || path.join(appRoot, "..", "fleet_management_front"));
const libDir = path.join(webRoot, "src", "lib");
const outDir = path.join(appRoot, "src", "i18n", "base");

const SOURCES = [
  { file: "i18n-messages.ts", constName: "EN", out: "en.ts" },
  { file: "i18n-messages-de.ts", constName: "DE", out: "de.ts" },
  { file: "i18n-messages-es.ts", constName: "ES", out: "es.ts" },
];

/** Extracts the object literal assigned to `export const NAME ... = { ... };`. */
function extractObject(source, constName) {
  const start = source.search(new RegExp(`export const ${constName}\\s*:[^=]*=\\s*\\{`));
  if (start < 0) throw new Error(`const ${constName} not found`);
  const open = source.indexOf("{", source.indexOf("=", start));
  let depth = 0;
  let inString = null;
  for (let i = open; i < source.length; i++) {
    const ch = source[i];
    if (inString) {
      if (ch === "\\") i++;
      else if (ch === inString) inString = null;
      continue;
    }
    if (ch === '"' || ch === "'" || ch === "`") inString = ch;
    else if (ch === "/" && source[i + 1] === "/") i = source.indexOf("\n", i);
    else if (ch === "{") depth++;
    else if (ch === "}" && --depth === 0) return source.slice(open, i + 1);
  }
  throw new Error(`unterminated object for ${constName}`);
}

fs.mkdirSync(outDir, { recursive: true });
for (const { file, constName, out } of SOURCES) {
  const source = fs.readFileSync(path.join(libDir, file), "utf8");
  // The literal only contains string keys and values: evaluating it is safe and exact.
  const dict = new Function(`return (${extractObject(source, constName)});`)();
  const strings = Object.fromEntries(Object.entries(dict).filter(([, v]) => typeof v === "string"));
  const body =
    `// Generated by scripts/sync-i18n.js from fleet_management_front/src/lib/${file}.\n` +
    `// Do not edit by hand: run \`node scripts/sync-i18n.js\` again after a web change.\n` +
    `export const BASE_${constName}: Record<string, string> = ${JSON.stringify(strings, null, 1)};\n`;
  fs.writeFileSync(path.join(outDir, out), body);
  console.log(`${out}: ${Object.keys(strings).length} entries`);
}
